mapper.select:
SELECT *
FROM shopwizard.tOrdOrderProdCode

    AND ProdCode LIKE CONCAT('%',#{pProdCode},'%')
    AND ProdName LIKE CONCAT('%',#{pProdName},'%')
    AND Keywrd LIKE CONCAT('%',#{pKeywrd},'%')
    AND Capa1 = #{pCapa1}
    AND Capa2 = #{pCapa2}
    AND MatchProdCode LIKE CONCAT('%',#{pMatchProdCode},'%')
    AND ShopCode LIKE CONCAT('%',#{pShopCode},'%')
    AND UseYn = #{pUseYn}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderProdCode

    AND ProdCode LIKE CONCAT('%',#{pProdCode},'%')
    AND ProdName LIKE CONCAT('%',#{pProdName},'%')
    AND Keywrd LIKE CONCAT('%',#{pKeywrd},'%')
    AND Capa1 = #{pCapa1}
    AND Capa2 = #{pCapa2}
    AND MatchProdCode LIKE CONCAT('%',#{pMatchProdCode},'%')
    AND ShopCode LIKE CONCAT('%',#{pShopCode},'%')
    AND UseYn = #{pUseYn}
